begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.rejects(q text) returns boolean language plpgsql as $$ begin execute q;return false;exception when insufficient_privilege or invalid_parameter_value or unique_violation or no_data_found or check_violation then return true;end $$;
insert into auth.users(id) values('11111111-1111-4111-8111-111111111111'),('33333333-3333-4333-8333-333333333333');
update public.user_roles set role='admin' where user_id='33333333-3333-4333-8333-333333333333';
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select pg_temp.ok(pg_temp.rejects('select public.admin_asset_settings(1048576)'),'user cannot change upload size');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_asset(gen_random_uuid(),'{"alt_text":"Forbidden"}')$q$),'user cannot modify assets');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_reorder_assets(gen_random_uuid(),array[]::uuid[])$q$),'user cannot reorder assets');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
create temp table ids(k text,id uuid);
insert into ids values('card',(public.admin_save_card_data('cards','{"title":"Asset fixture","slug":"__asset_fixture","status":"published","is_available":false}')->>'id')::uuid);
insert into ids values('first',(public.admin_save_card_asset((select id from ids where k='card'),'{"storage_path":"test/primary.png","alt_text":"First card artwork","image_type":"preview","is_primary":true}')).id);
insert into ids values('second',(public.admin_save_card_asset((select id from ids where k='card'),'{"storage_path":"test/hero.png","alt_text":"Hero illustration","image_type":"hero","is_primary":true}')).id);
select pg_temp.ok((select count(*)=1 from public.card_images where card_id=(select id from ids where k='card') and is_primary),'single primary');
select pg_temp.ok(public.get_card_detail((select id from ids where k='card'))->'preview_assets'->0->>'image_type'='hero','primary hero is public preview');
select pg_temp.ok((public.get_card_detail((select id from ids where k='card'))->'preview_assets'->0->>'is_primary')::boolean,'public projection marks primary');
select pg_temp.ok(pg_temp.rejects($q$update public.card_images set is_primary=true where id=(select id from ids where k='first')$q$),'unique primary database constraint');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_asset((select id from ids where k='card'),'{"storage_path":"test/no-alt.png","alt_text":" ","image_type":"hero"}')$q$),'alt text required');
select public.admin_reorder_assets((select id from ids where k='card'),array[(select id from ids where k='second'),(select id from ids where k='first')]);
select pg_temp.ok((select sort_order=0 from public.card_images where id=(select id from ids where k='second')),'asset order');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_reorder_assets((select id from ids where k='card'),array[(select id from ids where k='first'),gen_random_uuid()])$q$),'reject foreign asset IDs');
select pg_temp.ok((public.admin_asset_settings(1048576)->>'max_bytes')::integer=1048576,'configurable upload limit');
select pg_temp.ok(pg_temp.rejects('select public.admin_asset_settings(0)'),'invalid limit denied');
reset role;
select pg_temp.ok((select file_size_limit=1048576 from storage.buckets where id='card-assets'),'Storage uses configured limit');
select 'Asset manager constraints and permissions passed; fixtures rolled back.' as result;
rollback;
